wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        // One permitted fetch. A transport failure comes back as a value;
        // an out-of-allowlist URL traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat at {} fetched {} chars",
            now.seconds, fetched
        );
        let notified = notifier::notify(&message);

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
